script:
stage(1000, 600, "#fbfbf8");
title({
  hu: "Téglalap forgatása a hosszabb oldala mentén (Forgástest)",
  en: "Rotation of a rectangle along its longer side (Solid of revolution)"
});

param("a", {hu: "Első oldal (a)", en: "First side (a)"}, 1, 8, 4, 0.5, "cm");
param("b", {hu: "Második oldal (b)", en: "Second side (b)"}, 1, 8, 2, 0.5, "cm");
param("speed", {hu: "Forgási sebesség", en: "Rotation speed"}, 0.2, 3, 1, 0.1, "1/s");
toggle("showSolid", {hu: "Forgástest kitöltése", en: "Fill solid body"}, true);

let angle = 0; // Forgási szög (rad) / Rotation angle
update((dt, t) => {
  angle += 2 * PI * P.speed * dt; // Szög integrálása / Integrate angle
});

draw(t => {
  // 1. Oldalak és méretek meghatározása / Determine sides and dimensions
  const sideA = P.a;
  const sideB = P.b;

  // A hosszabb oldal a forgástengely (magasság: h), a rövidebb a sugár (r)
  // The longer side is the axis of rotation (height: h), the shorter is the radius (r)
  const h = max(sideA, sideB);
  const r = min(sideA, sideB);

  // Forgástest jellemzői / Characteristics of the revolution solid (cylinder)
  const V = PI * r * r * h; // Térfogat / Volume (cm³)
  const A_szin = 2 * PI * r * h + 2 * PI * r * r; // Teljes felszín / Total surface area (cm²)

  // 2. 3D kamera beállítása / Setup 3D camera view
  view3d({
    x: 500,
    y: 320,
    scale: 35, // pixel / cm
    yaw: t * 0.3 + 0.5, // lassan forgó kamera a szép rálátásért / slowly rotating camera
    pitch: deg(25), // enyhe felső rálátás / slight elevated view
    dist: 800
  });

  begin3();

  // Forgástengely rajzolása (Y tengely mentén) / Draw axis of rotation along Y axis
  arrow3([0, -h/2 - 1, 0], [0, h/2 + 1, 0], {stroke: C.gray, lw: 2});
  text3("Tengely / Axis", [0, h/2 + 1.2, 0], {size: 14, color: C.gray, align: "center"});

  // 3. Forgástest (henger) rajzolása / Draw the revolution solid (cylinder)
  const nSeg = 32;
  const topCirc = circle3([0, h/2, 0], "y", r, nSeg);
  const botCirc = circle3([0, -h/2, 0], "y", r, nSeg);

  // Palást felület elemei vagy kitöltés / Surface or fill
  if (P.showSolid) {
    face3(topCirc, {fill: C.blue, alpha: 0.2, stroke: null});
    face3(botCirc, {fill: C.blue, alpha: 0.2, stroke: null});

    // Palást alkotói / Lateral generators
    for (let i = 0; i < nSeg; i += 4) {
      path3([topCirc[i], botCirc[i]], {stroke: C.blue, alpha: 0.15, lw: 1});
    }
  }

  // Kontúr körök és élek / Contour circles and edges
  path3(topCirc, {stroke: C.blue, lw: 2.5}, true);
  path3(botCirc, {stroke: C.blue, lw: 2.5}, true);

  // Függőleges külső élek / Vertical outer edges
  path3([[-r, h/2, 0], [-r, -h/2, 0]], {stroke: C.blue, lw: 2});
  path3([[r, h/2, 0], [r, -h/2, 0]], {stroke: C.blue, lw: 2});

  // 4. A forgó téglalap kirajzolása 3D-ben / Draw the rotating rectangle in 3D
  const c = cos(angle);
  const s = sin(angle);

  // A téglalap 4 csúcsa a 3D térben / 4 corners of the rectangle in 3D space
  const p1 = [0, -h/2, 0];
  const p2 = [r * c, -h/2, r * s];
  const p3 = [r * c, h/2, r * s];
  const p4 = [0, h/2, 0];

  // Forgó téglalap lapja és kerete / Rotating rectangle face and border
  face3([p1, p2, p3, p4], {fill: C.orange, alpha: 0.6, stroke: C.ink});
  path3([p1, p2, p3, p4, p1], {stroke: C.ink, lw: 2.5}, true);

  end3();

  // 5. Adatok megjelenítése / Display readouts and plots
  show({hu: "Hosszabb oldal (magasság h)", en: "Longer side (height h)"}, h, "cm", 1);
  show({hu: "Rövidebb oldal (sugár r)", en: "Shorter side (radius r)"}, r, "cm", 1);
  show({hu: "Forgástest térfogata V", en: "Volume V"}, V, "cm³", 1);
  show({hu: "Forgástest felszíne A", en: "Surface area A"}, A_szin, "cm²", 1);

  plot({hu: "Térfogat V", en: "Volume V"}, V, {unit: "cm³", color: C.blue});
});
